class stringx {
  char *chars; void *my_buf;
public:
  stringx(const char *, int = -1); explicit stringx(int);
  stringx(const stringx &); ~stringx();
};
struct vector3d { float x, y, z; };
class TextString {
  void *font; stringx text; float x, y; int z, hJustify, vJustify;
  bool even_number_spacing; int fade; float fade_alpha, fade_timer, scale, button_scale;
  bool override_alpha;
public:
  bool checkTime; float time; bool no_color; unsigned int color;
  virtual ~TextString(); virtual void Update(float); virtual void Draw();
  virtual void setHJustify(int); virtual void setVJustify(int); virtual void setFont(void *);
  virtual void setButtonScale(float); virtual void numberSpacing(bool);
  virtual void changeText(stringx); virtual void changeScale(float);
  virtual void changePos(float, float); virtual void changeX(float); virtual void changeY(float);
  virtual void changeZ(int); virtual void ChangeFade(bool, bool, float); virtual void SetFade(float);
  virtual float getX(); virtual float getY(); virtual int getZ(); virtual stringx getText();
  virtual float GetScale() const; virtual float GetButtonScale() const;
  virtual bool GetNumberSpacing() const; virtual void *GetFont();
  virtual int GetHJustify() const; virtual int GetVJustify() const;
  virtual void setLineSpacing(int); virtual void resetLineSpacing();
  virtual void UpdateInScene(bool); virtual void SetLocation3D(vector3d);
  virtual vector3d GetLocation3D(); virtual void SetBehaviorNF(float, float);
  virtual void SetBehavior(bool);
protected:
  virtual void Render(); virtual void Render(stringx *, float, float);
  virtual void Render(stringx *, float, float, float *, float *, bool);
  virtual void cons(void *, stringx, float, float, int, float, int, int, bool, unsigned int);
};
class RandomText : public TextString {
  bool isRand, noFade; char rand_string[12];
public:
  virtual void Update(float); virtual void Draw(); virtual void changeText(stringx);
  virtual void makeRand(); virtual void unmakeRand(); void Break();
};
class TrickBoxText : public RandomText {
public:
  void Update(float); void Draw(); void changePos(float, float);
  void makeRand(); void unmakeRand(); void Break();
};
class ScoringManager {
public:
  class Chain { public: int GetScore() const; bool IsInteresting() const; };
  char pad[0x12a4]; Chain chain;
  const Chain &GetChain() const { return chain; }
};
class kellyslater_controller {
public:
  ScoringManager &get_my_scoreManager() { return *(ScoringManager *)this; }
};
class world_dynamics_system {
  char pad[0xf8]; kellyslater_controller *ks_controller[2];
public:
  kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};
class game {
  char pad[0xb4]; int num_ai_players;
public:
  int get_num_ai_players() { return num_ai_players; }
};
extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;
class IGOFrontEnd {
public:
  struct PLAYER {
    char pad[32]; TrickBoxText *trickText; TextString *trickAttrText;
    RandomText *trickPointText; char tail[16];
  };
private:
  char pad[0x11c]; int numPlayers; PLAYER *players;
  static int TRICK_WAIT_MAX;
public:
  void MakeTrickPointText(int, const stringx &);
  void OnTrickFail(const int playerIdx);
};
#define assert(x) ((void)0)

void IGOFrontEnd::OnTrickFail(const int playerIdx)
{
	assert(playerIdx >= 0 && playerIdx < numPlayers);

	kellyslater_controller *	ksctrl = g_world_ptr->get_ks_controller(playerIdx);

	if (g_game_ptr->get_num_ai_players() && playerIdx)
		return;

	// Make trick text red and have it bleed off screen.
	if (ksctrl->get_my_scoreManager().GetChain().IsInteresting())
	{
		players[playerIdx].trickText->makeRand();
		players[playerIdx].trickText->checkTime = true;
		players[playerIdx].trickText->time = TRICK_WAIT_MAX;
		players[playerIdx].trickText->Break();
		//players[playerIdx].trickBurstText->checkTime = true;
		//players[playerIdx].trickBurstText->time = 0.0f;

		MakeTrickPointText(playerIdx, stringx(ksctrl->get_my_scoreManager().GetChain().GetScore()));
		players[playerIdx].trickPointText->makeRand();
		players[playerIdx].trickPointText->checkTime = true;
		players[playerIdx].trickPointText->time = TRICK_WAIT_MAX;
		players[playerIdx].trickPointText->Break();
		//players[playerIdx].pointBurstText->checkTime = true;
		//players[playerIdx].pointBurstText->time = 0.0f;
	}

	players[playerIdx].trickAttrText->changeText("");
}
